#!/bin/bash
# make_artifacts_v5.sh (2026-10-28, numerics shift 16; v4 dbf64725 unchanged, plus: the section 8 recovery-test record (lead TH, RT-D met), the Stage III reading
# directories reports/stage3_r1 to stage3_r4 (primary-reported records; lead-accepted with conditions as dated addenda) with the R4 reading chain v2 script and log,
# and the operator's CPU_LIMIT.md as a hardware change of Stage III). v2, v3 and v4 are left unchanged and do not run.
# Run only after the lead's dated release of THIS version, CPU only, nice 19, before the lead's 14:00Z claims freeze on 2026-10-28; set -e stops the script at any missing file
# (the stage3_r4 copy needs the chain's post-run hashes file, so the R4 reading chain must have ended).
# (a) no '2>/dev/null || true' on the record lines; (b) explicit file lists for the record directories, directory copies for the reading directories with a per-file check;
# (c) artifacts/section8 and artifacts/reports/stage3_readings are removed before the copy (generated copies only); (d) section8/COPY_CHECK.sha256 compares every copy
# with its source and any mismatch exits 3; (e) README lines with the lead's wording (QY for the validation, QP for the resume test, TH for the recovery test).
set -e
ROOT=$(cd "$(dirname "$0")/.." && pwd); A=$ROOT/../artifacts
bash $ROOT/scripts/make_artifacts.sh
rm -rf $A/section8 $A/reports/stage3_readings                                                                        # (c)
mkdir -p $A/section8/validation $A/section8/resume_test $A/section8/recovery $A/reports/stage3_readings
V=$ROOT/runs/section8_validation
VAL_FILES="$V/RECORD.md $V/RECORD_CORRECTIONS_20261027.md $V/MODULE_HASHES.sha256 $V/IMPORTED_LANE_MODULES.txt $V/IMPORTED_LANE_MODULES_dynamic.txt $V/import_closure_stderr.txt $V/PREFLIGHT.txt $V/PREP_STAMP $V/compare_vt_nest10.py $V/compare_vt_nest10_v1_to_v2.diff $V/compare_vt_nest10_v2.py $V/vt_nest10_full/LAUNCH.txt $V/vt_nest10_full/stdout.log $V/vt_nest10_full/validate_full_nest10.json $V/vt_nest10_full/VT5_inputs.sha256 $V/vt_nest10_full/VT5_run.txt $V/vt_nest10_full/VT5_compare_v2.md $V/vt_nest10_full/VT5_compare_v2.json"   # (b)
R=$ROOT/runs/resume_test_rs_record_20261027
RES_FILES="$R/RECORD.md $R/LEDGER_ROWS_ADDED.jsonl $R/RESULT_FILES.sha256 $R/resume_test_preflight.txt $R/resume_test_rs_20261027T174857Z.log"   # (b)
C=$ROOT/runs/section8_recovery
REC_FILES="$C/RECORD.md $C/RECORD_ADDENDUM1_20261028.md $C/RECORD_TEMPLATE.md $C/rt_a_stamp.txt $C/status_before.txt $C/stop_output.txt $C/start_output.txt $C/status_after.txt $C/after_stamp.txt"   # (b)
for f in $VAL_FILES; do cp "$f" $A/section8/validation/; done                                                         # (a)
for f in $RES_FILES; do cp "$f" $A/section8/resume_test/; done                                                        # (a)
for f in $REC_FILES; do cp "$f" $A/section8/recovery/; done                                                           # (a)
for d in stage3_r1 stage3_r2 stage3_r3 stage3_r4; do cp -r $ROOT/reports/$d $A/reports/stage3_readings/; done          # (a)
cp $ROOT/runs/_logs/shift15/r4_reading_chain_v2.sh $ROOT/runs/_logs/shift15/r4_reading_chain_v2_20261028T011740Z.log $A/reports/stage3_readings/stage3_r4/   # (a)
cp $ROOT/../CPU_LIMIT.md $A/docs/CPU_LIMIT.md                                                                         # (a)
CHK=$A/section8/COPY_CHECK.sha256; : > $CHK; BAD=0                                                                    # (d)
for f in $VAL_FILES; do s=$(sha256sum "$f" | cut -d' ' -f1); c=$(sha256sum $A/section8/validation/$(basename "$f") | cut -d' ' -f1); if [ "$s" = "$c" ]; then v=MATCH; else v=MISMATCH; BAD=1; fi; echo "$v source $s copy $c section8/validation/$(basename "$f") <- runs/section8_validation/${f#$V/}" >> $CHK; done
for f in $RES_FILES; do s=$(sha256sum "$f" | cut -d' ' -f1); c=$(sha256sum $A/section8/resume_test/$(basename "$f") | cut -d' ' -f1); if [ "$s" = "$c" ]; then v=MATCH; else v=MISMATCH; BAD=1; fi; echo "$v source $s copy $c section8/resume_test/$(basename "$f") <- runs/resume_test_rs_record_20261027/$(basename "$f")" >> $CHK; done
for f in $REC_FILES; do s=$(sha256sum "$f" | cut -d' ' -f1); c=$(sha256sum $A/section8/recovery/$(basename "$f") | cut -d' ' -f1); if [ "$s" = "$c" ]; then v=MATCH; else v=MISMATCH; BAD=1; fi; echo "$v source $s copy $c section8/recovery/$(basename "$f") <- runs/section8_recovery/$(basename "$f")" >> $CHK; done
for d in stage3_r1 stage3_r2 stage3_r3 stage3_r4; do for f in $ROOT/reports/$d/*; do s=$(sha256sum "$f" | cut -d' ' -f1); c=$(sha256sum $A/reports/stage3_readings/$d/$(basename "$f") | cut -d' ' -f1); if [ "$s" = "$c" ]; then v=MATCH; else v=MISMATCH; BAD=1; fi; echo "$v source $s copy $c reports/stage3_readings/$d/$(basename "$f") <- reports/$d/$(basename "$f")" >> $CHK; done; done
for f in $ROOT/runs/_logs/shift15/r4_reading_chain_v2.sh $ROOT/runs/_logs/shift15/r4_reading_chain_v2_20261028T011740Z.log; do s=$(sha256sum "$f" | cut -d' ' -f1); c=$(sha256sum $A/reports/stage3_readings/stage3_r4/$(basename "$f") | cut -d' ' -f1); if [ "$s" = "$c" ]; then v=MATCH; else v=MISMATCH; BAD=1; fi; echo "$v source $s copy $c reports/stage3_readings/stage3_r4/$(basename "$f") <- runs/_logs/shift15/$(basename "$f")" >> $CHK; done
s=$(sha256sum $ROOT/../CPU_LIMIT.md | cut -d' ' -f1); c=$(sha256sum $A/docs/CPU_LIMIT.md | cut -d' ' -f1); if [ "$s" = "$c" ]; then v=MATCH; else v=MISMATCH; BAD=1; fi; echo "$v source $s copy $c docs/CPU_LIMIT.md <- ../CPU_LIMIT.md" >> $CHK
echo "copy check written $(date -u +%Y-%m-%dT%H:%M:%SZ): $(grep -c '^MATCH' $CHK) MATCH, $(grep -c '^MISMATCH' $CHK) MISMATCH" >> $CHK
if [ "$BAD" != 0 ]; then echo "COPY MISMATCH, see $CHK"; exit 3; fi
cat >> $A/README.md <<EOR
- section8/: the section 8 test records. validation/: the single-command validation of the saved nest10 state (c_l 0.45, omega 1, omega/c_l 20/9, R_0 = 0.3), ACCEPTED by the lead (d128 QY, 2026-10-27T19:17:17Z) as a reproduction of the saved nest10 diagnostics from a clean process: the command released as VT-1 ran once on GPU 0 with unchanged code and no training, 2026-10-27 16:45:11Z to 18:42:07Z (7016 s), exit 0; of the 89 rows 81 agree within 1e-6 relative (57 identical, 21 to rounding, 3 close; they include the holdout rho_u^max 0.04195 and 0.04145), 7 differ (rho_u_bal on both grids by about 5 per cent, cause OPEN and not cited; three Gram shell lists with 21 against 23 shells; two rounding-floor closure quantities) and 1 is definitional; the VT's new sections are unreviewed numbers and are not cited; this is not new evidence about the state, whose label stays C provisional; RECORD_CORRECTIONS_20261027.md lists the lead's corrections VC1 to VC13 to RECORD.md. resume_test/: the interruption-and-resume test of the deployed worker v2.4 on a disposable job (lead QP, a software resume test only). recovery/: the single-command recovery test (scripts/stop_supervisor.sh, then scripts/start_supervisor.sh, each from a new login shell, with an empty queue and no running job; 2026-10-28 02:49:03Z to 02:55:48Z; the old supervisor 3548537 exited 02:49:19Z, the new one 3972313 started 02:49:51Z with its first heartbeat 02:51:54Z; the queue and the 2405-row ledger byte-identical before and after), ACCEPTED by the lead (d128 TH, 2026-10-28T03:04:31Z) as a software test of the supervisor's stop and restart; its one open item (the STATUS.json best_rms figure changed with an identical ledger) was closed by the lead's reading (the old process held an older src/campaign/ledger.py 'latest' rule in memory) and RECORD_ADDENDUM1_20261028.md carries that closure and one wording correction (the saved status files hold three leaderboard rows each, not ten). COPY_CHECK.sha256: each copy's sha256 against its source.
- reports/stage3_readings/: the Stage III replication and perturbation readings R1 to R4 at c_l 0.45, omega 1, omega/c_l 20/9 (reader outputs, hashes files, plans; stage3_r4/ also holds the R4 reading chain v2 script and its log). Every value is primary-reported; the lead accepted each reading with conditions written as dated addenda in docs/NUM_REPORT.md, and the R4 reading record stands as the lead's dated note on it says; none is a gate entry and none makes any state a candidate.
- docs/CPU_LIMIT.md: the operator's CPU limit of 2026-10-28 01:50 UTC (the lane pinned to CPUs 0,2 from 01:46Z, at most two worker processes, OMP_NUM_THREADS=1), a hardware change during Stage III that slowed the CPU readers and the supervisor's first heartbeat after the recovery test.
EOR
(cd $A && find . -type f ! -name MANIFEST.sha256 -print0 | sort -z | xargs -0 sha256sum > MANIFEST.sha256)
du -sh $A | cut -f1; echo "artifacts (v5, with section8 recovery and Stage III readings) written $(date -u +%Y-%m-%dT%H:%M:%SZ)"
